insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"will_first_slash_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}},{"key":"will_first_slash_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}},{"key":"will_runaway_hammer_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}},{"key":"will_runaway_hammer_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}},{"key":"will_snoring_anvil_done","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}},{"key":"will_snoring_anvil_start","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\blacksmith.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"will_first_slash_done","locale":"he","line_order":0,"content":"אייתתם gib — גדול! עכשיו אתם מוכנים.","line_format":"plain_text"},{"dialogue_key":"will_first_slash_done","locale":"he","line_order":1,"content":"הנה היכולת Slash. נדנוד גדול… ואז שווווש!","line_format":"plain_text"},{"dialogue_key":"will_first_slash_start","locale":"he","line_order":0,"content":"הגיע הזמן לשיעור Slash האמיתי! קודם מילה קלה: gib.","line_format":"plain_text"},{"dialogue_key":"will_first_slash_start","locale":"he","line_order":1,"content":"ליד שער הממלכה סדרו את gib — נדנוד גדול לפני המכה.","line_format":"plain_text"},{"dialogue_key":"will_first_slash_start","locale":"he","line_order":2,"content":"חזרו אליי אחרי זה. יש לי הפתעה חדה בשבילכם.","line_format":"plain_text"},{"dialogue_key":"will_runaway_hammer_done","locale":"he","line_order":0,"content":"קיבלתי את ה־goL kaO! הפטיש חזר… עם שערות חתול עליו.","line_format":"plain_text"},{"dialogue_key":"will_runaway_hammer_done","locale":"he","line_order":1,"content":"זכרו: tac זה חתול. שלוש אותיות, אפס דרמה. כמעט.","line_format":"plain_text"},{"dialogue_key":"will_runaway_hammer_start","locale":"he","line_order":0,"content":"הפטיש שלי רץ אחרי חתול! בלי פטיש אני רק מכה באוויר.","line_format":"plain_text"},{"dialogue_key":"will_runaway_hammer_start","locale":"he","line_order":1,"content":"לכו למפרץ, סדרו את האותיות של tac, וקבלו goL kaO אחד.","line_format":"plain_text"},{"dialogue_key":"will_runaway_hammer_start","locale":"he","line_order":2,"content":"תביאו לי את ה־goL kaO — ואולי גם את הפטיש.","line_format":"plain_text"},{"dialogue_key":"will_snoring_anvil_done","locale":"he","line_order":0,"content":"קיבלתי את ה־sbreH. הסדן פקח עין אחת… ואז חייך.","line_format":"plain_text"},{"dialogue_key":"will_snoring_anvil_done","locale":"he","line_order":1,"content":"god זה כלב. עכשיו הסדן ער — ורועש שוב.","line_format":"plain_text"},{"dialogue_key":"will_snoring_anvil_start","locale":"he","line_order":0,"content":"הסדן נוחר. הוא מתעורר רק אם מספרים לו סיפור על כלב.","line_format":"plain_text"},{"dialogue_key":"will_snoring_anvil_start","locale":"he","line_order":1,"content":"ליד בית הבנאים סדרו את god. המשחק ייתן לכם sbreH אחד.","line_format":"plain_text"},{"dialogue_key":"will_snoring_anvil_start","locale":"he","line_order":2,"content":"תביאו את ה־sbreH — אני אשים אותו ליד האוזן של הסדן.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
